update core.identity_blocks_working set position=2147483647 where block_id=(select (ack->>'block_id')::uuid from saved);
select is(api.add_current_owner_spill_cta_block_working('{"action": "add_spill_cta_block", "base_collection_revision": 2, "is_visible": true, "spill_cta_working": {"kind": "spill_cta", "target": "owner_spill"}}'::jsonb)->>'status','position_exhausted','No unsafe append position');
insert into core.identity_blocks_working(block_id,owner_id,kind,position) select '24300000-0000-4000-8000-000000000011',owner_id,'text',11 from actors where auth_user_id='24300000-0000-4000-8000-000000000001';
select is(api.resolve_current_owner_spill_cta_block_working('24300000-0000-4000-8000-000000000011'),'{"status":"unavailable"}'::jsonb,'Wrong-kind read uniform');
insert into core.identity_blocks_working(block_id,owner_id,kind,position) select '24300000-0000-4000-8000-000000000012',owner_id,'spill_cta',12 from actors where auth_user_id='24300000-0000-4000-8000-000000000001';
select is(api.resolve_current_owner_spill_cta_block_working('24300000-0000-4000-8000-000000000012')#>>'{block,payload_state}','missing','Membership never infers typed marker');
select is(api.resolve_current_owner_spill_cta_block_working('24300000-0000-4000-8000-000000000012')#>'{block,spill_cta_working}','null'::jsonb,'Missing marker never infers semantic ready payload');
select throws_ok($$insert into core.identity_block_spill_cta_working(block_id,owner_id,kind) select '24300000-0000-4000-8000-000000000011',owner_id,'spill_cta' from actors where auth_user_id='24300000-0000-4000-8000-000000000001'$$,'23503',null,'Cannot attach marker to Text member');
insert into core.identity_blocks_working(owner_id,kind,position) select owner_id,'text',n from actors cross join generate_series(100,1095) n where auth_user_id='24300000-0000-4000-8000-000000000001';
select is(api.add_current_owner_spill_cta_block_working('{"action":"add_spill_cta_block","base_collection_revision":2,"is_visible":true,"spill_cta_working":{"kind":"spill_cta","target":"owner_spill"}}')->>'status','unavailable','Inherited membership resource bound preserved');
delete from core.identity_blocks_working where position between 100 and 1095;
delete from core.identity_blocks_working where block_id=(select (ack->>'block_id')::uuid from saved);
select is((select count(*) from core.identity_block_spill_cta_working),1::bigint,'Removal cascades own marker only');
select is((select count(*) from core.identity_publications where owner_id in(select owner_id from actors)),0::bigint,'Working never publishes Identity');
select is((select count(*) from core.spill_item_publications where owner_id in(select owner_id from actors)),0::bigint,'Working never activates Spill');
select * from finish();
rollback;
